config.script:
// whatsapp_orcamento — agente `script`. Comportamento = ESTE arquivo (DADO), nunca código de serviço.
//
// Gatilho: alguém da equipe ABRE um orçamento (a tela do orçamento ou uma aba dela).
//   1. lê o orçamento aberto para saber o paciente;
//   2. mostra a QUEM ABRIU um BOTÃO flutuante no canto inferior esquerdo, "Conversa com o paciente",
//      que leva à conversa do paciente na Central de Conversas (link interno). Some ao trocar de tela.
//   3. orçamento sem paciente: sai limpo, sem botão.
//
// Quem vê: só quem pode ler o orçamento (requer_permissoes) — o agente lê com o papel dele, então o botão
// exige a mesma leitura de quem o vê.
// Sem dado pessoal: o botão não traz nome; o ref leva só ids opacos (paciente e quem abriu); o resumo, só flags.
//
// Injetados: event, config, context, call() -> {ok,status_code,body}, log(), result().

var ev = event || {};
var params = ev.params || {};
var usuario = ev.usuario || {};
var ROTA = '/orcamento/:id';

function txt(v) { return (v === undefined || v === null) ? '' : String(v).trim(); }
function unwrap(r) {
  if (!r || !r.ok) return null;
  var b = r.body;
  return (b && b.data !== undefined) ? b.data : b;
}
function sair(resumo, ret) { result(resumo); return ret; }

var orcamentoId = txt(params.id);
var quem = txt(usuario.username) || txt(usuario.id);
if (!orcamentoId || !quem) {
  log('whatsapp_orcamento: navegação sem orçamento ou sem usuário', 'warning');
  return sair({ botao: false, pulado: 'sem_contexto' }, { ok: true, botao: false, pulado: 'sem_contexto' });
}

var ro = call('buscar_orcamento', { id: orcamentoId });
var orc = unwrap(ro);
if (!orc) {
  log('whatsapp_orcamento: FALHA ao ler o orçamento (HTTP ' + ((ro && ro.status_code) || '?') + ')', 'warning');
  return sair({ botao: false, acao_bloqueada: true, etapa: 'buscar_orcamento', http: (ro && ro.status_code) || null },
              { ok: false, erro: 'buscar_orcamento' });
}
var clienteId = txt(orc.cliente_id) || txt(orc.cliente && orc.cliente.id);
if (!/^[A-Za-z0-9_-]{1,128}$/.test(clienteId)) {
  return sair({ botao: false, pulado: 'sem_paciente' }, { ok: true, botao: false, pulado: 'sem_paciente' });
}

var corpo = {
  type: 'diretiva_ui', kind: 'snippet',
  componente: 'botao',
  posicao: { ancora: 'inf-esq', dx: 24, dy: 24 },
  estilo: { cor: '#25D366', icone: 'whatsapp', variante: 'cheio' },
  titulo: 'Conversa com o paciente',
  botoes: [{ label: 'Conversa com o paciente', estilo: 'primary',
             acao: { tipo: 'link', href: '/conversas/cliente/' + clienteId } }],
  duracao: { tipo: 'tela' }, persistencia: 'efemero',
  rota: { padrao: ROTA, params: { id: orcamentoId } },
  requer_permissoes: ['orcamento:read'],
  ref: 'whatsapp-orcamento:' + clienteId + ':' + quem,
  alvo: { user_id: quem }
};
if (txt(ev.navegacao_id)) corpo.navegacao_id = txt(ev.navegacao_id);

var r = call('emitir_snippet', corpo);
if (!r || !r.ok) {
  log('whatsapp_orcamento: FALHA ao mostrar o botão (HTTP ' + ((r && r.status_code) || '?') + ')', 'warning');
  return sair({ botao: false, acao_bloqueada: true, etapa: 'emitir_snippet', http: (r && r.status_code) || null },
              { ok: false, erro: 'emitir_snippet' });
}
return sair({ botao: true }, { ok: true, botao: true });
